            <label class="field-label">{{ $t('auth.password') }}</label>
            <div class="field" :class="{ 'field--focus': focusPass, 'field--error': passError }">
              <span class="field-icon"><v-icon size="18" color="#94a3b8">mdi-lock-outline</v-icon></span>
              <input
                  v-model="password"
                  :type="showPassword ? 'text' : 'password'"
                  :placeholder="$t('auth.passwordPlaceholder')"
                  autocomplete="current-password"
                  @focus="focusPass = true" @blur="focusPass = false"
                  :disabled="isShowAuthLoader || isAuthSuccess"
              />
              <button class="show-btn" @click="togglePasswordVisibility" type="button">
                <v-icon size="18" color="#94a3b8">
                  {{ showPassword ? 'mdi-eye-off-outline' : 'mdi-eye-outline' }}
                </v-icon>
              </button>
            </div>
          </div>
        </div>

        <button
            class="submit-btn"
            :class="{ 'submit-btn--loading': isShowAuthLoader, 'submit-btn--success': isAuthSuccess }"
            :disabled="!availableConfirmBtn || isShowAuthLoader || isAuthSuccess"
            @click="checkAuth"
        >
          <span v-if="isAuthSuccess" class="btn-content">
            <v-icon size="18">mdi-check</v-icon> {{ $t('auth.success') }}
          </span>
