<script>
import {ROLE_HOME, AUTH_URL} from '@/config/managers.config'

export default {
  name: 'LoginComponent',
  emits: ['updateUserStatus'],

  data() {
    return {
      login: '',
      password: '',
      showPassword: false,
      focusLogin: false,
      focusPass: false,
      loginError: false,
      passError: false,
      isShowAuthLoader: false,
      isAuthSuccess: false,
      snackbar: false,
      snackbarText: '',
      dialog: false,
      dialogTitle: '',
      dialogText: '',
    }
  },

  computed: {
    availableConfirmBtn() {
      return this.validateLogin(this.login) && this.validatePass(this.password)
    },
  },

  mounted() {
    document.addEventListener('keydown', this.handleEnter)
  },
  beforeUnmount() {
    document.removeEventListener('keydown', this.handleEnter);
    this.login = '';
    this.password = ''
  },

  methods: {
    togglePasswordVisibility() {
      if (this.isShowAuthLoader || this.isAuthSuccess) return
      this.showPassword = !this.showPassword
    },
    handleEnter(event) {
      if (event.key === 'Enter' && this.availableConfirmBtn) this.checkAuth()
    },
    validateLogin(value) {
      return typeof value === 'string' && value.trim().length > 0
    },
    validatePass(value) {
      return typeof value === 'string' && value.trim().length > 0
    },
    showDialog(title, text) {
      this.dialogTitle = title;
      this.dialogText = text;
      this.dialog = true
    },
    normalizeRole(role) {
      return String(role || '').trim().toLowerCase()
    },

    async checkAuth() {
      if (this.isShowAuthLoader || this.isAuthSuccess || !this.availableConfirmBtn) return

      this.isShowAuthLoader = true
      this.isAuthSuccess = false

      try {
        const res = await fetch(AUTH_URL)
        const response = await res.json()

        if (!response || !Array.isArray(response.stuff)) {
          throw new Error('Invalid auth response format')
        }

        const user = response.stuff.find(item => item.LoginName === this.login.trim())

        if (!user) {
          this.showDialog(this.$t('auth.notFound'), this.$t('auth.notFoundMsg'))
          return
        }
        if (user.PasswordEmail !== this.password.trim()) {
          this.showDialog(this.$t('auth.wrongPass'), this.$t('auth.wrongPassMsg'))
          return
        }

        const authObj = {login: user.LoginName, role: this.normalizeRole(user.RoleStatus)}
        localStorage.setItem('sale-auth', JSON.stringify(authObj))
        this.isAuthSuccess = true
        this.$emit('updateUserStatus', authObj)
        setTimeout(() => {
          this.$router.replace(ROLE_HOME[authObj.role] || '/')
        }, 800)

      } catch (error) {
        console.error(error)
        this.snackbarText = this.$t('auth.serverError')
        this.snackbar = true
      } finally {
        if (!this.isAuthSuccess) this.isShowAuthLoader = false
      }
    },
  },
}
</script>

